<script setup lang="ts">
const route = useRoute(); const router = useRouter(); const id = computed(() => String(route.params.learningVoidId)); const journey = useLearnV2Journey(id); const index = ref(0); const response = ref(''); const confidence = ref(3); const objective = computed(() => journey.objectives.value[index.value] ?? null)
async function submit() { if (!objective.value || !response.value.trim()) return; await journey.submitCalibrationAttempt(objective.value.id, response.value, confidence.value); response.value = ''; index.value++ }
async function finish() { await journey.completeCalibration(); await router.push(`/app/learn/${id.value}?section=plan`) }
</script>
<template><main class="mx-auto max-w-2xl px-4 py-8"><NuxtLink :to="`/app/learn/${id}`" class="text-sm text-muted-foreground hover:text-foreground">← Back to workspace</NuxtLink><section v-if="!journey.mission" class="mt-6" aria-live="polite">Preparing calibration…</section><section v-else class="mt-6"><p class="font-inter text-xs uppercase tracking-wide text-primary">Calibration</p><h1 class="mt-1 font-dm-sans text-2xl font-bold">Find your starting point</h1><p class="mt-2 text-sm text-muted-foreground">Cold attempts tailor the plan. They cannot award retained mastery.</p><UiCard v-if="objective" class="mt-6 p-5"><p class="text-sm text-muted-foreground">Capability {{ index + 1 }} of up to 7</p><h2 class="mt-2 font-dm-sans text-lg font-semibold">{{ objective.capability }}</h2><textarea v-model="response" rows="6" class="mt-4 w-full rounded-lg border border-input bg-background p-3 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" placeholder="Write your best answer before seeing any teaching…" /><label class="mt-4 block text-sm">How confident are you? <select v-model.number="confidence" class="ml-2 rounded border border-input bg-background px-2 py-1"><option v-for="value in 5" :key="value" :value="value">{{ value }} / 5</option></select></label><UiButton class="mt-5" :disabled="!response.trim() || journey.busy" @click="submit">Submit cold attempt</UiButton></UiCard><UiCard v-else class="mt-6 p-5"><h2 class="font-dm-sans text-lg font-semibold">Ready to build your plan?</h2><p class="mt-2 text-sm text-muted-foreground">Complete at least three calibration attempts before continuing.</p><UiButton class="mt-4" :disabled="journey.busy" @click="finish">Build plan preview</UiButton></UiCard><p v-if="journey.error" role="alert" class="mt-4 text-sm text-destructive">{{ journey.error }}</p></section></main></template>
